#include <iostream>
#include <string>
#include <vector>
#include <chrono>
int main() {
  auto start = std::chrono::high_resolution_clock::now();
  std::string longString; 
  for (int i = 0; i < 100000; ++i) {
    longString += "a";
  }
  auto end = std::chrono::high_resolution_clock::now();
  auto duration = std::chrono::duration_cast<std::chrono::microseconds>(end - start);
  std::cout << "Time taken by naive concatenation: " << duration.count() << " microseconds" << std::endl;
  start = std::chrono::high_resolution_clock::now();
  std::string efficientString;
  efficientString.reserve(100000); // Reserve space to avoid repeated allocations
  for (int i = 0; i < 100000; ++i) {
    efficientString += "a";
  }
  end = std::chrono::high_resolution_clock::now();
  duration = std::chrono::duration_cast<std::chrono::microseconds>(end - start);
  std::cout << "Time taken by efficient concatenation: " << duration.count() << " microseconds" << std::endl;
  return 0;
}
